def temp_setattr(
    obj, attr: str, value, condition: bool = True
) -> Generator[None, None, None]:


    if condition:
        old_value = getattr(obj, attr)
        setattr(obj, attr, value)
    try:
        yield obj
    finally:
        if condition:
            setattr(obj, attr, old_value)

