        res = []
        diff = np.abs(np.diff(route, axis=0))
        turning = np.diff(diff, axis=0)[:, 0]
        indexes = np.where(turning == -1)[0] + 1
        for index in indexes:
            grid = route[index]
            if not self[grid].is_fleet:
                res.append(grid)
            else:
                if (index > 1) and (index + 1 not in indexes):
