def model_fingerprint(
    config_file: Text,
    domain: Optional[Union[Domain, Text]] = None,
    nlu_data: Optional[Text] = None,
    stories: Optional[Text] = None,
) -> Fingerprint:



    import rasa
    import time

    if isinstance(domain, Domain):
        domain_hash = hash(domain)
    else:
        domain_hash = _get_hashes_for_paths(domain)

    return {
        FINGERPRINT_CONFIG_KEY: _get_hashes_for_paths(config_file),
        FINGERPRINT_DOMAIN_KEY: domain_hash,
        FINGERPRINT_NLU_DATA_KEY: _get_hashes_for_paths(nlu_data),
        FINGERPRINT_STORIES_KEY: _get_hashes_for_paths(stories),
        FINGERPRINT_TRAINED_AT_KEY: time.time(),
        FINGERPRINT_RASA_VERSION_KEY: rasa.__version__,
    }

def get_models_for_finetuning(
    previous_model_file: Optional[Text], trained_models_directory: Text,
) -> Tuple[Optional["Agent"], Optional["Interpreter"]]:


    from rasa.core.agent import Agent
    from rasa.core.interpreter import RasaNLUInterpreter
    from rasa.nlu.model import Interpreter

    if previous_model_file == USE_LATEST_MODEL_FOR_FINE_TUNING:
        previous_model_file = get_latest_model(trained_models_directory)

    if previous_model_file is None or not Path(previous_model_file).is_file():
        return None, None

    with unpack_model(previous_model_file) as unpacked:
        core, nlu = None, None
        try:
            core = Agent.load(unpacked)
        except ModelNotFound:
            # Something went wrong when loading Core model. Apparently it's not there.
            pass

        # Try using loaded `interpreter` from `Agent` to avoid loading it twice.
        if isinstance(core.interpreter, RasaNLUInterpreter):
            return core, core.interpreter.interpreter

        try:
            _, nlu_directory = get_model_subdirectories(unpacked)
            nlu = Interpreter.load(nlu_directory)
        except Exception:
            # Anything might go wrong. In that case we skip model finetuning.
            pass

    return core, nlu

def get_models_for_finetuning(
    previous_model_file: Optional[Union[Path, Text]]
) -> Tuple[Optional["Agent"], Optional["Interpreter"]]:


    from rasa.core.interpreter import RasaNLUInterpreter

    if Path(previous_model_file).is_dir():
        logger.debug(
            f"Trying to load latest model from '{previous_model_file}' for "
            f"finetuning."
        )
        previous_model_file = get_latest_model(previous_model_file)

    if previous_model_file is None or not Path(previous_model_file).is_file():
        logger.debug(
            "No valid model for finetuning found as directory either "
            "contains no model or model file cannot be found."
        )
        return None, None

    with unpack_model(previous_model_file) as unpacked:
        core = _load_core_model(unpacked)

        # Try using loaded `interpreter` from `Agent` to avoid loading it twice.
        if core and isinstance(core.interpreter, RasaNLUInterpreter):
            nlu = core.interpreter.interpreter
        else:
            nlu = _load_nlu_model(unpacked)

    return core, nlu

def should_retrain(
    new_fingerprint: Fingerprint, old_model: Text, train_path: Text
) -> FingerprintComparisonResult:



    fingerprint_comparison = FingerprintComparisonResult()

    if old_model is None or not os.path.exists(old_model):
        return fingerprint_comparison

    with unpack_model(old_model) as unpacked:
        last_fingerprint = fingerprint_from_path(unpacked)
        old_core, old_nlu = get_model_subdirectories(unpacked)

        fingerprint_comparison = FingerprintComparisonResult(
            core=did_section_fingerprint_change(
                last_fingerprint, new_fingerprint, SECTION_CORE
            ),
            nlu=did_section_fingerprint_change(
                last_fingerprint, new_fingerprint, SECTION_NLU
            ),
            nlg=did_section_fingerprint_change(
                last_fingerprint, new_fingerprint, SECTION_NLG
            ),
        )

        core_merge_failed = False
        if not fingerprint_comparison.should_retrain_core():
            target_path = os.path.join(train_path, DEFAULT_CORE_SUBDIRECTORY_NAME)
            core_merge_failed = not move_model(old_core, target_path)
            fingerprint_comparison.core = core_merge_failed

        if not fingerprint_comparison.should_retrain_nlg() and core_merge_failed:
            # If moving the Core model failed, we should also retrain NLG
            fingerprint_comparison.nlg = True

        if not fingerprint_comparison.should_retrain_nlu():
            target_path = os.path.join(train_path, "nlu")
            fingerprint_comparison.nlu = not move_model(old_nlu, target_path)

        return fingerprint_comparison

